/// 🎓 Model for an End-of-Level Exam Question
class LevelExamQuestion {
  final String id;
  final String question;
  final List<String> options;
  final int correctIndex;
  final String explanation;
  final String hint;
  final String category; // 'Vocab', 'Grammar', 'Speaking', 'Listening', 'Syntax', 'Phonics'

  const LevelExamQuestion({
    required this.id,
    required this.question,
    required this.options,
    required this.correctIndex,
    required this.explanation,
    required this.hint,
    this.category = 'Grammar',
  });
}

/// 📝 Interactive End-of-Level Mastery Exam Dialog
/// Requirement:
/// - Levels 1 to 5 correspond to Cyber Cat, Cyber Fox, Shadow Wolf, Royal Tiger, Golden Lion.
/// - 6 distinct Syllabus Tracks (Zero Foundation, Beginner, Elementary, Middle, Advanced, Expert).
/// - Changing the syllabus track immediately alters the questions to match that track's difficulty!
/// - Real exam flow: Question 1 to 5, user ticks answers.
/// - End of Exam shows complete Learning Corrections:
///   - Shows user's answer (✅ or ❌)
///   - Shows correct answer
///   - Shows detailed grammatical explanation & hint for deep learning
/// - Pass mark is 50% (3 out of 5 questions correct) required to unlock the next level!
class PocketLevelExamDialog extends StatefulWidget {
  final int level;
  final LearnerLevel trackLevel;
  final VoidCallback? onExamPassed;

  const PocketLevelExamDialog({
    super.key,
    required this.level,
    this.trackLevel = LearnerLevel.zero,
    this.onExamPassed,
  });

  static Future<bool> show(
    BuildContext context, {
    required int level,
    LearnerLevel? trackLevel,
    VoidCallback? onExamPassed,
  }) async {
    final effectiveTrack = trackLevel ?? await PocketSyllabusRepository.getSavedLevel();
    if (!context.mounted) return false;
    final result = await showDialog<bool>(
      context: context,
      barrierDismissible: false,
      builder: (ctx) => PocketLevelExamDialog(
        level: level,
        trackLevel: effectiveTrack,
        onExamPassed: onExamPassed,
      ),
    );
    return result ?? false;
  }

  @override
  State<PocketLevelExamDialog> createState() => _PocketLevelExamDialogState();
}

class _PocketLevelExamDialogState extends State<PocketLevelExamDialog>
    with SingleTickerProviderStateMixin {
  final FlutterTts _tts = FlutterTts();

  late List<LevelExamQuestion> _questions;
  int _currentIndex = 0;
  late List<int?> _selectedAnswers;
  int? _currentSelection;

  bool _isExamCompleted = false;
  int _score = 0;
  bool _isSpeaking = false;

  late AnimationController _celebrationController;

  static String getAnimalName(int day) {
    switch (day) {
      case 1:
        return 'Cyber Cat';
      case 2:
        return 'Cyber Fox';
      case 3:
        return 'Shadow Wolf';
      case 4:
        return 'Royal Tiger';
      case 5:
        return 'Golden Lion';
      case 6:
        return 'Mighty Elephant';
      case 7:
        return 'Ninja Panda';
      case 8:
        return 'Noble Bear';
      case 9:
        return 'Cyber Ape';
      case 10:
        return 'Majestic Eagle';
      case 11:
        return 'Shadow Leopard';
      case 12:
        return 'Cosmic Unicorn';
      case 13:
        return 'Solar Phoenix';
      case 14:
        return 'Armored Rhino';
      case 15:
        return 'Thunder Bison';
      case 16:
        return 'Mystic Croc';
      default:
        return 'Level $day';
    }
  }

  @override
  void initState() {
    super.initState();
    _celebrationController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 900),
    );

    _initQuestions();
    _initTts();
  }

  void _initTts() {
    _tts.setLanguage('en-US');
    _tts.setSpeechRate(0.48);
    _tts.setPitch(1.0);
  }

  @override
  void dispose() {
    _tts.stop();
    _celebrationController.dispose();
    super.dispose();
  }

  void _speakText(String text) async {
    try {
      setState(() => _isSpeaking = true);
      await _tts.speak(text);
      if (mounted) setState(() => _isSpeaking = false);
    } catch (_) {
      if (mounted) setState(() => _isSpeaking = false);
    }
  }

  void _initQuestions() {
    final questions = _generateQuestionsForLevel(widget.level, widget.trackLevel);
    _questions = List.from(questions);
    _currentIndex = 0;
    _selectedAnswers = List<int?>.filled(questions.length, null);
    _currentSelection = null;
    _isExamCompleted = false;
    _score = 0;
  }

  void _onAnswerSelected(int index) {
    HapticFeedback.selectionClick();
    setState(() {
      _currentSelection = index;
    });
  }

  void _proceedToNext() {
    if (_currentSelection == null) return;
    _selectedAnswers[_currentIndex] = _currentSelection;

    if (_currentIndex < _questions.length - 1) {
      HapticFeedback.lightImpact();
      setState(() {
        _currentIndex++;
        _currentSelection = _selectedAnswers[_currentIndex];
      });
    } else {
      _finishAndCalculateScore();
    }
  }

  Future<void> _finishAndCalculateScore() async {
    int correctCount = 0;
    for (int i = 0; i < _questions.length; i++) {
      if (_selectedAnswers[i] == _questions[i].correctIndex) {
        correctCount++;
      }
    }

    // 🌟 User Audio Directive: Exactly 8 Questions per Exam, Minimum 5/8 to Pass!
    const passMark = 5;
    final isPassed = correctCount >= passMark;

    setState(() {
      _score = correctCount;
      _isExamCompleted = true;
    });

    if (isPassed) {
      _celebrationController.forward(from: 0.0);
      HapticFeedback.heavyImpact();
      SystemSound.play(SystemSoundType.click);
      await _persistExamPass();
    } else {
      HapticFeedback.vibrate();
    }
  }

  Future<void> _persistExamPass() async {
    final uid = SupaFlow.client.auth.currentUser?.id;
    final prefs = await SharedPreferences.getInstance();
    final todayStr = '${DateTime.now().year}-${DateTime.now().month}-${DateTime.now().day}';

    if (uid != null) {
      await Learning60DayService().completeDailyMission(
        userId: uid,
        day: widget.level,
        earnedPoints: 200,
        advanceToNextDay: false,
      );
      await prefs.setBool('pocket_day_${uid}_${widget.level}_completed', true);
      await prefs.setBool('pocket_level_exam_${uid}_${widget.level}_passed', true);
      await prefs.setString('learning_day_${uid}_${widget.level}_completed_date', todayStr);
      await prefs.setInt('learning_day_${uid}_${widget.level}_completed_timestamp', DateTime.now().millisecondsSinceEpoch);
      await prefs.setInt('learning_last_completed_day_$uid', widget.level);

      await PocketFortressDefenseService.recordActivityPoints('daily_mission');
      await PocketFortressDefenseService.awardPoints(200);
    }

    widget.onExamPassed?.call();
  }

  /// 🎯 Adaptive Question Generator based on Level & Syllabus Track
  List<LevelExamQuestion> _generateQuestionsForLevel(int level, LearnerLevel track) {
    List<LevelExamQuestion> rawList = [];

    if (level == 1) {
      final examQuestions = Day1Curriculum.getExam();
      rawList = examQuestions.map((eq) => LevelExamQuestion(
        id: 'day1_exam_${eq.index}',
        question: eq.questionEn,
        options: eq.options,
        correctIndex: eq.correctAnswer is int ? eq.correctAnswer as int : 0,
        explanation: eq.explanationEn.isNotEmpty ? eq.explanationEn : eq.explanationMl,
        hint: eq.questionMl,
        category: 'House 1 Gatekeeper',
      )).toList();
    } else if (level >= 1 && level <= 90) {
      switch (track) {
        case LearnerLevel.zero:
          rawList = _buildZeroFoundationQuestionsForDay(level);
          break;
        case LearnerLevel.beginner:
          rawList = _buildBeginnerQuestionsForDay(level);
          break;
        case LearnerLevel.elementary:
          rawList = _buildElementaryQuestionsForDay(level);
          break;
        case LearnerLevel.middle:
          rawList = _buildMiddleQuestionsForDay(level);
          break;
        case LearnerLevel.advanced:
          rawList = _buildAdvancedQuestionsForDay(level);
          break;
        case LearnerLevel.expert:
          rawList = _buildExpertQuestionsForDay(level);
          break;
      }
    }

    if (rawList.isEmpty) {
      rawList = _buildCurriculumQuestionsForLevel(level);
    }

    // 🌟 User Audio Directive: Exactly 8 Questions per Exam across all 90 Days!
    return _ensureExactly8Questions(rawList, level);
  }

  /// 🌟 Guarantees exactly 8 distinct questions per exam for any level (Days 1 to 90)
  List<LevelExamQuestion> _ensureExactly8Questions(List<LevelExamQuestion> base, int level) {
    if (base.length == 8) return base;
    if (base.length > 8) return base.sublist(0, 8);

    final result = List<LevelExamQuestion>.from(base);
    final vocab = Pocket90DayVocabCurriculum.getVocabForDay(level);

    int vocabIdx = 0;
    while (result.length < 8) {
      final qNum = result.length + 1;
      if (vocabIdx < vocab.length) {
        final item = vocab[vocabIdx];
        if (qNum == 6) {
          result.add(
            LevelExamQuestion(
              id: 'q_gen_${level}_6',
              question: 'What is the meaning of "${item.word}" in Malayalam?',
              options: [
                item.malayalamMeaning,
                'വിരുദ്ധമായ അർത്ഥം (Opposite)',
                'മറ്റൊരു പദം (Different term)',
                'അപ്രസക്തമായ വാക്ക് (Irrelevant)',
              ],
              correctIndex: 0,
              explanation: '"${item.word}" translates to "${item.malayalamMeaning}".',
              hint: item.definition,
              category: 'Vocab',
            ),
          );
        } else if (qNum == 7) {
          final exampleSentence = item.exampleSentence;
          final blankSentence = exampleSentence.replaceAll(RegExp(r'\b' + RegExp.escape(item.word) + r'\b', caseSensitive: false), '_____');
          result.add(
            LevelExamQuestion(
              id: 'q_gen_${level}_7',
              question: 'Complete the sentence: "$blankSentence"',
              options: [
                item.word,
                'wrongly',
                'quickly',
                'happily',
              ],
              correctIndex: 0,
              explanation: '"${item.word}" correctly completes the sentence: "$exampleSentence"',
              hint: 'Today\'s core vocabulary word.',
              category: 'Syntax',
            ),
          );
        } else {
          result.add(
            LevelExamQuestion(
              id: 'q_gen_${level}_$qNum',
              question: 'How do you use "${item.word}" in conversation?',
              options: [
                item.exampleSentence,
                'I not speak ${item.word}',
                'The word ${item.word} is no good',
                'Never use ${item.word} anywhere',
              ],
              correctIndex: 0,
              explanation: 'A natural conversational example: "${item.exampleSentence}".',
              hint: 'Look for the natural grammatically correct sentence.',
              category: 'Speaking',
            ),
          );
        }
        vocabIdx++;
      } else {
        result.add(
          LevelExamQuestion(
            id: 'q_gen_${level}_$qNum',
            question: 'Which of the following is a grammatically correct English sentence for Day $level?',
            options: [
              'She speaks English with confidence and clarity.',
              'She speaking English not good.',
              'She speaked English wrongly.',
              'She don\'t speaks English well.',
            ],
            correctIndex: 0,
            explanation: '"She speaks English with confidence and clarity" follows correct third-person singular subject-verb agreement.',
            hint: 'Third person singular "she" takes the verb with -s.',
            category: 'Grammar',
          ),
        );
      }
    }
    return result;
  }

