  // 📚 2. BEGINNER TRACK (Days 1 to 5)
  // ==========================================
  List<LevelExamQuestion> _buildBeginnerQuestionsForDay(int day) {
    switch (day) {
      case 1: // 🐱 Day 1: Cyber Cat
        return [
          const LevelExamQuestion(
            id: 'b_1_1',
            question: 'Why should you avoid saying "Myself Rahul" in English self-introductions?',
            options: [
              '"Myself" is reflexive; standard English uses "My name is Rahul" or "I am Rahul".',
              'Because "Myself" is only used by politicians.',
              'Because you must always say your surname first.',
              'There is no issue, both are equally standard.',
            ],
            correctIndex: 0,
            explanation: 'Saying "Myself [Name]" is a common Manglish habit. Always say "My name is..." or "I am...".',
            hint: 'Reflexive pronouns cannot stand as grammatical subjects.',
            category: 'Speaking',
          ),
          const LevelExamQuestion(
            id: 'b_1_2',
            question: 'Complete the question: "Where ___ you come from?"',
            options: ['do', 'are', 'is', 'does'],
            correctIndex: 0,
            explanation: 'In present simple questions with "you", use the auxiliary verb "do".',
            hint: 'Subject "you" pairs with "do", not "does".',
            category: 'Grammar',
          ),
          const LevelExamQuestion(
            id: 'b_1_3',
            question: 'Which sentence correctly uses the present simple tense?',
            options: [
              'He drinks tea every morning.',
              'He drink tea every morning.',
              'He drinking tea every morning.',
              'He is drink tea every morning.',
            ],
            correctIndex: 0,
            explanation: 'Third-person singular subjects (He, She, It) take an "-s" ending: "drinks".',
            hint: 'He/She + verb-s.',
            category: 'Grammar',
