  /// Builds 5 to 6 questions dynamically from curriculum registry for Level > 5
  List<LevelExamQuestion> _buildCurriculumQuestionsForLevel(int level) {
    final List<LevelExamQuestion> questions = [];
    final vocab = PocketMissionCurriculumRegistry.getVocabItems(level);
    final quizQ = PocketMissionCurriculumRegistry.getQuizQuestion(level);
    final quizOpts = PocketMissionCurriculumRegistry.getQuizOptions(level);
    final shortcut = PocketMissionCurriculumRegistry.getFluencyShortcut(level);
    final workout = PocketMissionCurriculumRegistry.getEnglishThinkingWorkout(level);

    if (vocab.isEmpty && quizQ.isEmpty) {
      return questions;
    }

    if (vocab.isNotEmpty) {
      final v0 = vocab[0];
      final wrongMeanings = vocab.length > 1
          ? vocab.skip(1).take(3).map((v) => v.definition).toList()
          : <String>['To sleep quietly', 'To jump high', 'A large vehicle'];

      questions.add(
        LevelExamQuestion(
          id: 'lvl_${level}_q1_vocab',
          question: 'Level $level Vocabulary: What is the meaning of "${v0.word}"?',
          options: [
            v0.malayalamMeaning.isNotEmpty ? '${v0.definition} (${v0.malayalamMeaning})' : v0.definition,
            ...wrongMeanings
          ]..shuffle(math.Random(level * 11)),
          correctIndex: 0, // will be resolved
          explanation: '"${v0.word}" means ${v0.definition}. Example: "${v0.exampleSentence}".',
          hint: 'Phonetic: [${v0.phonetic}].',
          category: 'Vocab',
        ),
      );
    }

    if (quizQ.isNotEmpty && quizOpts.length >= 4) {
      questions.add(
        LevelExamQuestion(
          id: 'lvl_${level}_q2_quiz',
          question: 'Level $level Challenge: $quizQ',
          options: quizOpts,
          correctIndex: 0,
          explanation: 'Core rule taught in Day $level curriculum lesson.',
          hint: 'Recall the grammar rule taught today.',
          category: 'Grammar',
        ),
      );
    }

    if (shortcut.title.isNotEmpty && shortcut.examples.isNotEmpty) {
      questions.add(
        LevelExamQuestion(
          id: 'lvl_${level}_q3_shortcut',
          question: 'Fluency Shortcut (${shortcut.title}): Which usage is natural?',
          options: [
            shortcut.examples.first,
            'Avoid this in everyday conversation',
            'Both sentences are wrong',
            'None of the above',
          ],
          correctIndex: 0,
          explanation: 'Shortcut Hack: ${shortcut.quickHack}.',
          hint: shortcut.ruleSummary,
          category: 'Speaking',
        ),
      );
    }

    if (workout.situation.isNotEmpty && workout.instantResponses.isNotEmpty) {
      questions.add(
        LevelExamQuestion(
          id: 'lvl_${level}_q4_thinking',
          question: 'Instant Reflex: "${workout.situation}"\nWhat is the natural English response?',
          options: [
            workout.instantResponses.first,
            'Stay silent and do not reply',
            'Translate every word literally from Malayalam',
            'Say whatever words come to mind',
          ],
          correctIndex: 0,
          explanation: 'Direct English thought: "${workout.directEnglishThought}".',
          hint: 'Spoken reflex response.',
          category: 'Speaking',
        ),
      );
    }

    if (vocab.length > 2) {
      final v2 = vocab[2];
      questions.add(
        LevelExamQuestion(
          id: 'lvl_${level}_q5_mastery',
          question: 'Level $level Application: Complete the sentence:\n"${v2.exampleSentence.replaceAll(RegExp(RegExp.escape(v2.word), caseSensitive: false), '________')}"',
          options: [
            v2.word,
            ...vocab.where((v) => v.word != v2.word).take(3).map((v) => v.word),
          ]..shuffle(math.Random(level * 29)),
          correctIndex: 0,
          explanation: '"${v2.word}" is correct: "${v2.exampleSentence}".',
          hint: 'Meaning: ${v2.definition}.',
          category: 'Syntax',
        ),
      );
    }

    return questions;
  }

