  /// 🌟 Complete Results & Detailed Learning Corrections Review Dialog (Audio Directive!)
  Widget _buildCorrectionsReviewDialog() {
    final animalName = getAnimalName(widget.level);
    final total = _questions.length;
    final pct = ((_score / total) * 100).round();
    final isPassed = _score >= (total / 2).ceil();

    return Dialog(
      backgroundColor: const Color(0xFF0F172A),
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(24),
        side: BorderSide(
          color: isPassed ? const Color(0xFF10B981) : const Color(0xFFFF8906),
          width: 2,
        ),
      ),
      insetPadding: const EdgeInsets.symmetric(horizontal: 16, vertical: 20),
      child: ConstrainedBox(
        constraints: const BoxConstraints(maxWidth: 440, maxHeight: 680),
        child: Padding(
          padding: const EdgeInsets.all(20),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              // Header
              Row(
                children: [
                  Text(
                    isPassed ? '🎉' : '⚠️',
                    style: const TextStyle(fontSize: 24),
                  ),
                  const SizedBox(width: 10),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          'DAY ${widget.level} EXAM RESULTS: ${animalName.toUpperCase()}',
                          style: GoogleFonts.outfit(
                            color: isPassed ? const Color(0xFF10B981) : const Color(0xFFFF8906),
                            fontSize: 13.5,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                        Text(
                          isPassed
                              ? 'Level Mastered! Review corrections below.'
                              : '50% Pass Mark Required (3/5). Review corrections & retake.',
                          style: GoogleFonts.inter(
                            color: Colors.white70,
                            fontSize: 11,
                          ),
                        ),
                      ],
                    ),
                  ),
                  IconButton(
                    icon: const Icon(Icons.close_rounded, color: Colors.white54, size: 20),
                    onPressed: () => Navigator.pop(context, isPassed),
                  ),
                ],
              ),
              const SizedBox(height: 12),

              // Score Summary Card
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 10),
                decoration: BoxDecoration(
                  color: isPassed
                      ? const Color(0xFF10B981).withValues(alpha: 0.12)
                      : const Color(0xFFFF8906).withValues(alpha: 0.12),
                  borderRadius: BorderRadius.circular(14),
                  border: Border.all(
                    color: isPassed ? const Color(0xFF10B981).withValues(alpha: 0.4) : const Color(0xFFFF8906).withValues(alpha: 0.4),
                  ),
                ),
                child: Row(
                  mainAxisAlignment: MainAxisAlignment.spaceAround,
                  children: [
                    Column(
                      children: [
                        Text('YOUR SCORE', style: GoogleFonts.inter(color: Colors.white54, fontSize: 10)),
                        const SizedBox(height: 2),
                        Text('$_score / $total', style: GoogleFonts.outfit(color: Colors.white, fontSize: 16, fontWeight: FontWeight.bold)),
                      ],
                    ),
                    Container(width: 1, height: 26, color: Colors.white12),
                    Column(
                      children: [
                        Text('ACCURACY', style: GoogleFonts.inter(color: Colors.white54, fontSize: 10)),
                        const SizedBox(height: 2),
                        Text('$pct%', style: GoogleFonts.outfit(color: isPassed ? const Color(0xFF10B981) : const Color(0xFFFF8906), fontSize: 16, fontWeight: FontWeight.bold)),
                      ],
                    ),
                    Container(width: 1, height: 26, color: Colors.white12),
                    Column(
                      children: [
                        Text('STATUS', style: GoogleFonts.inter(color: Colors.white54, fontSize: 10)),
                        const SizedBox(height: 2),
                        Text(
                          isPassed ? 'PASSED ✓' : 'RETRY ↻',
                          style: GoogleFonts.outfit(
                            color: isPassed ? const Color(0xFF10B981) : const Color(0xFFFF8906),
                            fontSize: 14,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                      ],
                    ),
                  ],
                ),
              ),
              if (!isPassed)
                Container(
                  margin: const EdgeInsets.only(top: 10),
                  padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
                  decoration: BoxDecoration(
                    color: const Color(0xFFDC2626).withValues(alpha: 0.15),
                    borderRadius: BorderRadius.circular(10),
                    border: Border.all(color: const Color(0xFFEF4444).withValues(alpha: 0.4)),
                  ),
                  child: Row(
                    children: [
                      const Text('🔒', style: TextStyle(fontSize: 16)),
                      const SizedBox(width: 8),
                      Expanded(
                        child: Text(
                          'Pass mark is 60% (At least 3 out of 5 required). House ${widget.level + 1} will unlock only after you pass this Gate Exam! Check your mistakes below and retry.',
                          style: GoogleFonts.inter(color: const Color(0xFFFCA5A5), fontSize: 11, fontWeight: FontWeight.w600),
                        ),
                      ),
                    ],
                  ),
                ),
              const SizedBox(height: 12),

              // Title for Detailed Corrections List
              Row(
                children: [
                  const Icon(Icons.spellcheck_rounded, color: Color(0xFFFFD700), size: 16),
                  const SizedBox(width: 6),
                  Text(
                    'DETAILED LEARNING CORRECTIONS',
                    style: GoogleFonts.outfit(
                      color: const Color(0xFFFFD700),
                      fontSize: 11.5,
                      fontWeight: FontWeight.w900,
                      letterSpacing: 0.4,
                    ),
                  ),
                ],
              ),
              const SizedBox(height: 8),

              // Scrollable Corrections List
              Expanded(
                child: ListView.separated(
                  physics: const BouncingScrollPhysics(),
                  itemCount: _questions.length,
                  separatorBuilder: (_, __) => const SizedBox(height: 10),
                  itemBuilder: (context, i) {
                    final q = _questions[i];
                    final userAnsIdx = _selectedAnswers[i];
                    final isCorrect = userAnsIdx == q.correctIndex;
                    final correctText = q.options[q.correctIndex];
                    final userText = (userAnsIdx != null && userAnsIdx < q.options.length)
                        ? q.options[userAnsIdx]
                        : 'Skipped';

                    return Container(
                      padding: const EdgeInsets.all(12),
                      decoration: BoxDecoration(
                        color: const Color(0xFF1E293B),
                        borderRadius: BorderRadius.circular(12),
                        border: Border.all(
                          color: isCorrect
                              ? const Color(0xFF10B981).withValues(alpha: 0.4)
                              : const Color(0xFFEF4444).withValues(alpha: 0.4),
                          width: 1.1,
                        ),
                      ),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Row(
                            children: [
                              Text(
                                'Q${i + 1}: ',
                                style: GoogleFonts.outfit(
                                  color: const Color(0xFFFFD700),
                                  fontWeight: FontWeight.bold,
                                  fontSize: 12,
                                ),
                              ),
                              Expanded(
                                child: Text(
                                  q.question,
                                  style: GoogleFonts.outfit(
                                    color: Colors.white,
                                    fontSize: 12,
                                    fontWeight: FontWeight.w600,
                                  ),
                                ),
                              ),
                              Icon(
                                isCorrect ? Icons.check_circle_rounded : Icons.cancel_rounded,
                                color: isCorrect ? const Color(0xFF10B981) : const Color(0xFFEF4444),
                                size: 16,
                              ),
                            ],
                          ),
                          const SizedBox(height: 6),

                          // If correct
                          if (isCorrect) ...[
                            Container(
                              width: double.infinity,
                              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
                              decoration: BoxDecoration(
                                color: const Color(0xFF10B981).withValues(alpha: 0.12),
                                borderRadius: BorderRadius.circular(8),
                              ),
                              child: Text(
                                '✅ Your Answer: "$correctText"',
                                style: GoogleFonts.inter(
                                  color: const Color(0xFF86EFAC),
                                  fontSize: 11,
                                  fontWeight: FontWeight.w600,
                                ),
                              ),
                            ),
                          ] else ...[
                            // If wrong
                            Container(
                              width: double.infinity,
                              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
                              decoration: BoxDecoration(
                                color: const Color(0xFFEF4444).withValues(alpha: 0.12),
                                borderRadius: BorderRadius.circular(8),
                              ),
                              child: Text(
                                '❌ Your Answer: "$userText"',
                                style: GoogleFonts.inter(
                                  color: const Color(0xFFFCA5A5),
                                  fontSize: 11,
                                  fontWeight: FontWeight.w600,
                                ),
                              ),
                            ),
                            const SizedBox(height: 4),
                            Container(
                              width: double.infinity,
                              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
                              decoration: BoxDecoration(
                                color: const Color(0xFF10B981).withValues(alpha: 0.12),
                                borderRadius: BorderRadius.circular(8),
                              ),
                              child: Text(
                                '✅ Correct Answer: "$correctText"',
                                style: GoogleFonts.inter(
                                  color: const Color(0xFF86EFAC),
                                  fontSize: 11,
                                  fontWeight: FontWeight.bold,
                                ),
                              ),
                            ),
                          ],

                          const SizedBox(height: 6),
                          // Explanation & Rule
                          Text(
                            '💡 Rule: ${q.explanation}',
                            style: GoogleFonts.inter(
                              color: Colors.white70,
                              fontSize: 10.5,
                              height: 1.35,
                            ),
                          ),
                        ],
                      ),
                    );
                  },
                ),
              ),

              const SizedBox(height: 12),

              // Action Buttons
              if (isPassed) ...[
                // 📸 Share Milestone Card to Vibes (Audio Directive!)
                SizedBox(
                  width: double.infinity,
                  height: 46,
                  child: ElevatedButton.icon(
                    style: ElevatedButton.styleFrom(
                      backgroundColor: const Color(0xFF0284C7),
                      foregroundColor: Colors.white,
                      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
                      elevation: 4,
                    ),
                    icon: const Icon(Icons.photo_camera_rounded, color: Colors.white, size: 20),
                    label: Text(
                      'SHARE CARD TO VIBES 📸 (സ്റ്റാറ്റസ് ഇടുക)',
                      style: GoogleFonts.outfit(fontWeight: FontWeight.w900, fontSize: 13),
                    ),
                    onPressed: () {
                      PocketLevelMilestoneVibeCardDialog.show(
                        context,
                        level: widget.level,
                        score: _score,
                        total: _questions.length,
                        onContinue: () => Navigator.pop(context, true),
                      );
                    },
                  ),
                ),
                const SizedBox(height: 8),

                SizedBox(
                  width: double.infinity,
                  height: 44,
                  child: ElevatedButton(
                    style: ElevatedButton.styleFrom(
                      backgroundColor: const Color(0xFF10B981),
                      foregroundColor: Colors.black,
                      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
                    ),
                    onPressed: () => Navigator.pop(context, true),
                    child: Text(
                      'CLAIM & ADVANCE TO LEVEL ${widget.level + 1} 🎓',
                      style: GoogleFonts.outfit(fontWeight: FontWeight.w900, fontSize: 13),
                    ),
                  ),
                ),
                const SizedBox(height: 6),
                Row(
                  children: [
                    Expanded(
                      child: TextButton.icon(
                        onPressed: () {
                          setState(() {
                            _initQuestions();
                          });
                        },
                        icon: const Icon(Icons.refresh_rounded, size: 14, color: Colors.white54),
                        label: Text(
                          'RE-TAKE FOR 100% ↺',
                          style: GoogleFonts.outfit(color: Colors.white70, fontSize: 11, fontWeight: FontWeight.bold),
                        ),
                      ),
                    ),
                    Expanded(
                      child: TextButton.icon(
                        onPressed: () {
                          Navigator.pop(context);
                          Navigator.push(
                            context,
                            MaterialPageRoute(builder: (_) => const SubscriptionPage()),
                          );
                        },
                        icon: const Icon(Icons.workspace_premium_rounded, size: 14, color: Color(0xFFFFD700)),
                        label: Text(
                          'BINGE PASS 👑',
                          style: GoogleFonts.outfit(color: const Color(0xFFFFD700), fontSize: 11, fontWeight: FontWeight.bold),
                        ),
                      ),
                    ),
                  ],
                ),
              ] else ...[
                SizedBox(
                  width: double.infinity,
                  height: 44,
                  child: ElevatedButton.icon(
                    style: ElevatedButton.styleFrom(
                      backgroundColor: const Color(0xFFFF8906),
                      foregroundColor: Colors.black,
                      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
                    ),
                    onPressed: () {
                      setState(() {
                        _initQuestions();
                      });
                    },
                    icon: const Icon(Icons.refresh_rounded, size: 18),
                    label: Text(
                      'RETRY EXAM TO PASS (MINIMUM 5/8 NEEDED) ↺',
                      style: GoogleFonts.outfit(fontWeight: FontWeight.w900, fontSize: 12.5),
                    ),
                  ),
                ),
              ],
            ],
          ),
        ),
      ),
    );
  }
}
